    ctx.Mode = MODE_RESET; ctx.TransferVectorOfSubComponents("Key", w);
    if (w[2].value != 0) ok = false;
    ctx.Mode = MODE_LOAD_TEXT; ctx.TransferVectorOfSubComponents("Key", w);
    if (ctx.textLoads != 1 || ctx.crcChecks != 4) ok = false;
